def longest(strings: List[str]) -> Optional[str]:
    if not strings:
        return None

    max_length = 0
    for s in strings:
        length = len(s)
        if length > max_length:
            max_length = length

    result = ""
    for s in strings:
        if len(s) == max_length:
            result = s
            break

    return result

